// Generated by `pnpm nx g @app/generators:action views.create`. Requests go through the real router
// with createTestEngine().inject. They fail until createViewsCreateAction is implemented; do not weaken them.
import { viewsCreate } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createViewsCreateAction,
  createWorkspaceFakeDeps,
} from '@app/svc-workspace';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () => createViewsCreateAction(createWorkspaceFakeDeps());
const def = viewsCreate;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('POST /views', () => {
  it('GP-1 (OQ-380) the route runs views.create only where a connection can be armed: with no connection the prod lock answers 422', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/views',
      payload: {
        name: 'Busy queues',
        kind: 'queues',
        definition: { filter: 'orders' },
      },
      headers: { 'idempotency-key': KEY },
    });

    // The router sends no environment class, so the call is "prod" and a command is locked until its
    // connection is armed (OQ-283). This command has no connection, so nothing can arm it: the gate
    // has no fix. OQ-380 asks for the rule; when it lands this test becomes the 200 of the golden path.
    expect(answer.statusCode).toBe(422);
    expect(answer.json()).toMatchObject({ code: 'GATE_BLOCKED' });
    expect(def.output.safeParse(answer.json()).success).toBe(false);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'POST',
      path: '/views',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold workspace.write gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'POST',
      path: '/views',
      payload: {
        name: 'Busy queues',
        kind: 'queues',
        definition: { filter: 'orders' },
      },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/views',
      payload: { unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 a method nothing is bound to on the path is 405, and Allow lists the bound ones', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PATCH',
      path: '/views',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('GET, POST');
  });
});
